using System.ComponentModel.DataAnnotations;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OrcaFacil.Application.Accounts;using OrcaFacil.Application.Abstractions;using OrcaFacil.Application.Accounts.Admin;using OrcaFacil.Application.Auth;using OrcaFacil.Application.Plans;using OrcaFacil.Domain.Plans;using OrcaFacil.Domain.Entities;using OrcaFacil.Domain.Enums;using OrcaFacil.Persistence;using OrcaFacil.Web.Security;
namespace OrcaFacil.Web.Pages.AccountAdmin.Users;[Authorize(Policy="AccountAdmin")]public sealed class NewModel(OrcaFacilDbContext db,ICurrentAccountService current,IPasswordHasher hasher,LoginIdentifierService identifiers,IPlanAccessService plans,IAccountInvitationService invitations):PageModel{[BindProperty]public InputModel Input{get;set;}=new();public IEnumerable<string>Profiles=>ProfilePermissionMatrix.AccountProfiles.Where(x=>ProfilePermissionMatrix.CanAssign(current.AccountRoleCode??"",x));public sealed class InputModel{[Required,StringLength(180)]public string Name{get;set;}="";[Required,EmailAddress]public string Email{get;set;}="";public string? Document{get;set;}public string TemporaryPassword{get;set;}="";[Required]public string Profile{get;set;}="ReadOnly";[BindProperty]public bool InviteByEmail{get;set;}}
public async Task<IActionResult>OnPostAsync(CancellationToken ct){if(current.AccountId is not Guid account)return Forbid();if(current.UserId==Guid.Empty)return Forbid();if(!ModelState.IsValid)return Page();if(!Input.InviteByEmail&&(string.IsNullOrWhiteSpace(Input.TemporaryPassword)||Input.TemporaryPassword.Length<10)){ModelState.AddModelError("Input.TemporaryPassword","Informe uma senha temporária com pelo menos 10 caracteres (ou marque o envio de convite por e-mail).");return Page();}var memberLimit=await plans.GetLimitAsync(account,PlanFeatureCodes.TeamMembersLimit,ct);if(memberLimit.HasValue){var activeMembers=await db.AccountMembers.CountAsync(x=>x.AccountId==account&&!x.IsDeleted,ct);var pendingInvites=Input.InviteByEmail?await invitations.CountPendingAsync(account,ct):0;if(AccountInvitationRules.TeamCapReached(memberLimit,activeMembers,pendingInvites)){ModelState.AddModelError(string.Empty,$"Seu plano permite até {memberLimit.Value} pessoa(s) na conta. Faça upgrade para convidar mais gente e continuar crescendo.");return Page();}}if(!ProfilePermissionMatrix.CanAssign(current.AccountRoleCode??"",Input.Profile)){ModelState.AddModelError("Input.Profile","Você não pode atribuir este perfil.");return Page();}var email=Input.Email.Trim().ToLowerInvariant();
if(Input.InviteByEmail){var created=await invitations.CreateAsync(account,email,Input.Name.Trim(),Input.Profile,current.UserId,HttpContext.TraceIdentifier,ct);if(!created.Succeeded){ModelState.AddModelError("Input.Email",created.Error??"Não foi possível criar o convite.");return Page();}TempData["InviteSent"]=true;TempData["InviteEmail"]=email;return RedirectToPage("Index");}
var user=await db.Users.SingleOrDefaultAsync(x=>x.Email==email&&!x.IsDeleted,ct);if(user is null){NormalizedLoginIdentifier? doc=null;if(!string.IsNullOrWhiteSpace(Input.Document)){try{doc=identifiers.Normalize(Input.Document);if(doc.Kind==LoginIdentifierKind.Email)ModelState.AddModelError("Input.Document","Informe um CPF ou CNPJ.");else if(await db.Users.AnyAsync(x=>x.DocumentNumber==doc.Value&&!x.IsDeleted,ct))ModelState.AddModelError("Input.Document","CPF/CNPJ já cadastrado.");}catch(ArgumentException ex){ModelState.AddModelError("Input.Document",ex.Message);}}if(!ModelState.IsValid)return Page();user=new UserAccount{Name=Input.Name.Trim(),Email=email,PasswordHash=hasher.Hash(Input.TemporaryPassword),MustChangePassword=true,DocumentNumber=doc?.Value,DocumentType=doc is null?null:doc.Kind==LoginIdentifierKind.Cnpj?BrazilianDocumentType.CNPJ:BrazilianDocumentType.CPF};db.Users.Add(user);}if(await db.AccountMembers.AnyAsync(x=>x.AccountId==account&&x.UserId==user.Id&&!x.IsDeleted,ct)){ModelState.AddModelError(string.Empty,"Este usuário já pertence à conta.");return Page();}var member=new AccountMember{AccountId=account,UserId=user.Id,RoleCode=Input.Profile};member.Join();db.AccountMembers.Add(member);db.AccountModuleAuditLogs.Add(new(){AccountId=account,ActorUserId=current.UserId,Action="AccountUserCreated",EntityType=nameof(AccountMember),EntityId=member.Id.ToString(),Summary=$"Usuário vinculado com perfil {Input.Profile}.",CorrelationId=HttpContext.TraceIdentifier});await db.SaveChangesAsync(ct);return RedirectToPage("Index");}}
